dashboard.definition:
{
  "title": "Excel Export Demo (Dashboard Studio)",
  "description": "Dashboard Studio cannot load custom JavaScript: the export is a plain link to the /services/excel_export endpoint.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_events": {
      "type": "ds.search",
      "name": "events",
      "options": {
        "query": "| makeresults count=250\n| streamstats count AS n\n| eval host=\"web-0\".(n%5+1), status=case(n%10==0,500, n%7==0,404, true(),200), bytes=random()%100000, response_ms=round((random()%2000)/10,1), user_id=substr(\"000000\".n,-6), _time=_time-(n*60)\n| table _time host status bytes response_ms user_id",
        "enableSmartSources": true
      }
    }
  },
  "visualizations": {
    "viz_export": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Export to Excel\n\n**1. Reuse the job of the dashboard** (sid of the `events` data source, no second search):\n\n[⬇ Download Excel - events](/splunkd/__raw/services/excel_export?sid=$events:job.sid$&filename=events&sheet=Events)\n\n**2. Run a search from the link** (`search` parameter, URL-encoded SPL, time range from the time picker):\n\n[⬇ Download Excel - summary by host](/splunkd/__raw/services/excel_export?search=%7C%20makeresults%20count%3D250%20%7C%20streamstats%20count%20AS%20n%20%7C%20eval%20host%3D%22web-0%22.%28n%255%2B1%29%2C%20bytes%3Drandom%28%29%25100000%20%7C%20stats%20count%20AS%20events%2C%20sum%28bytes%29%20AS%20total_bytes%20by%20host&earliest=$global_time.earliest$&latest=$global_time.latest$&filename=summary_by_host&sheet=Summary)"
      }
    },
    "viz_table": {
      "type": "splunk.table",
      "title": "Events (click a row to download them as .xlsx)",
      "dataSources": {
        "primary": "ds_events"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/splunkd/__raw/services/excel_export?sid=$events:job.sid$&filename=events_drilldown&sheet=Events",
            "newTab": false
          }
        }
      ]
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440
    },
    "globalInputs": [
      "input_time"
    ],
    "structure": [
      {
        "item": "viz_export",
        "type": "block",
        "position": { "x": 0, "y": 0, "w": 1440, "h": 230 }
      },
      {
        "item": "viz_table",
        "type": "block",
        "position": { "x": 0, "y": 230, "w": 1440, "h": 420 }
      }
    ]
  }
}
